var COPY_ICON='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>',CHECK_ICON='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>';document.addEventListener("DOMContentLoaded",function(){var e=document.querySelectorAll("div.highlight");e.forEach(function(e){var t=document.createElement("button");t.className="copy-code-btn",t.innerHTML=COPY_ICON,t.setAttribute("aria-label","Copy code"),t.addEventListener("click",function(){var n=e.querySelector("code");if(!n)return;navigator.clipboard.writeText(n.textContent).then(function(){t.innerHTML=CHECK_ICON,t.classList.add("copied"),setTimeout(function(){t.innerHTML=COPY_ICON,t.classList.remove("copied")},2e3)})}),e.appendChild(t)})})